// Four small stacks make a growing numerical pattern inspectable in real 3D.
import * as THREE from '../../vendor/three/three.module.min.js';
import {OrbitControls} from '../../vendor/three/OrbitControls.js';
export class PatternGrowthView{
 constructor(host,t,onFill,onMove){this.t=t;this.onFill=onFill;this.renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));this.renderer.outputColorSpace=THREE.SRGBColorSpace;this.canvas=this.renderer.domElement;this.canvas.tabIndex=0;this.canvas.setAttribute('aria-label','四组可以转动的积木。拖动改变视角；可点击第四组空位，或使用放一块按钮。');host.append(this.canvas);
  this.scene=new THREE.Scene();this.camera=new THREE.PerspectiveCamera(35,1,.1,100);this.camera.position.set(7,6,10);this.controls=new OrbitControls(this.camera,this.canvas);this.controls.target.set(0,1.75,0);this.controls.enablePan=false;this.controls.minDistance=7;this.controls.maxDistance=24;this.controls.update();
  this.scene.add(new THREE.HemisphereLight(0xffffff,0x88918d,2));const sun=new THREE.DirectionalLight(0xffffff,2);sun.position.set(-3,8,5);this.scene.add(sun);
  this.box=new THREE.BoxGeometry(.56,.56,.56);this.edges=new THREE.EdgesGeometry(this.box);this.edge=new THREE.LineBasicMaterial({color:0x354848});this.ghostEdge=new THREE.LineBasicMaterial({color:0x9da7a1,transparent:true,opacity:.5});const grad=new THREE.DataTexture(new Uint8Array([90,180,255]),3,1,THREE.RedFormat);grad.needsUpdate=true;grad.minFilter=grad.magFilter=THREE.NearestFilter;this.gradient=grad;
  this.mats=[0x83bbaa,0xe7bd7a,0x9aaed0,0xc992a0].map(color=>new THREE.MeshToonMaterial({color,gradientMap:grad}));this.ghost=new THREE.MeshBasicMaterial({color:0x9ba9a1,transparent:true,opacity:.09,depthWrite:false});this.cells=[];this.targets=[];
  [...t.known,t.target].forEach((count,col)=>{for(let i=0;i<count;i++){const g=new THREE.Group(),mesh=new THREE.Mesh(this.box,this.mats[col]),edge=new THREE.LineSegments(this.edges,this.edge);mesh.userData.index=i;g.add(mesh,edge);g.position.set((col-1.5)*1.28,i*.6+.3,0);g.userData={col,index:i};this.scene.add(g);this.cells.push(g);if(col===3)this.targets.push(g);}});
  this.floor=new THREE.Mesh(new THREE.CylinderGeometry(4.5,4.5,.12,48),new THREE.MeshToonMaterial({color:0xf0ecdf,gradientMap:grad}));this.floor.position.y=-.12;this.scene.add(this.floor);this.raycaster=new THREE.Raycaster();this.canvas.addEventListener('pointerdown',e=>this.down=[e.clientX,e.clientY]);this.canvas.addEventListener('pointerup',e=>{if(!this.down||Math.hypot(e.clientX-this.down[0],e.clientY-this.down[1])>5)return;const r=this.canvas.getBoundingClientRect();this.raycaster.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),this.camera);const hit=this.raycaster.intersectObjects(this.targets.map(g=>g.children[0])).find(h=>!this.model?.board?.filled.includes(h.object.userData.index));if(hit)this.onFill(hit.object.userData.index);});
  this.controls.addEventListener('start',()=>{this.start=this.camera.position.clone();});this.controls.addEventListener('end',()=>{if(this.start&&this.start.distanceTo(this.camera.position)>.001)onMove?.();});this.controls.addEventListener('change',()=>this.render());this.resizeObserver=new ResizeObserver(()=>this.resize());this.resizeObserver.observe(host);this.resize();
 }
 attach(host){host.append(this.canvas);this.resizeObserver.disconnect();this.resizeObserver.observe(host);this.resize();}
 resize(){const host=this.canvas.parentElement;if(!host)return;const r=host.getBoundingClientRect(),w=r.width||600,h=r.height||320;this.renderer.setSize(w,h,false);this.camera.aspect=w/h;this.camera.updateProjectionMatrix();this.render();}
 update(m){this.model=m;for(const g of this.targets){const filled=m.board.filled.includes(g.userData.index);g.children[0].material=filled?this.mats[3]:this.ghost;g.children[1].material=filled?this.edge:this.ghostEdge;}this.render();}
 turn(){const offset=this.camera.position.clone().sub(this.controls.target);offset.applyAxisAngle(new THREE.Vector3(0,1,0),Math.PI/4);this.camera.position.copy(this.controls.target.clone().add(offset));this.controls.update();this.render();}
 restoreCamera(v){if(!v)return;this.camera.position.fromArray(v.position);this.controls.target.fromArray(v.target);this.controls.update();this.render();}
 snapshot(){return{camera:this.camera.position.toArray(),target:this.controls.target.toArray(),cells:this.cells.map(g=>({column:g.userData.col,index:g.userData.index,position:g.position.toArray()}))};}
 render(){this.renderer.render(this.scene,this.camera);}
 destroy(){this.resizeObserver.disconnect();this.controls.dispose();this.box.dispose();this.edges.dispose();this.edge.dispose();this.ghostEdge.dispose();this.mats.forEach(m=>m.dispose());this.ghost.dispose();this.floor.geometry.dispose();this.floor.material.dispose();this.gradient.dispose();this.renderer.dispose();this.renderer.forceContextLoss();this.canvas.remove();}
}
